1	use std::ops::Range;
2	
3	use crate::{
4	    Span, SyntaxKind, SyntaxNode, is_newline, parse, reparse_block, reparse_markup,
5	};
6	
7	/// Refresh the given syntax node with as little parsing as possible.
8	///
9	/// Takes the new text, the range in the old text that was replaced and the
10	/// length of the replacement and returns the range in the new text that was
11	/// ultimately reparsed.
12	///
13	/// The high-level API for this function is
14	/// [`Source::edit`](crate::Source::edit).
15	pub fn reparse(
16	    root: &mut SyntaxNode,
17	    text: &str,
18	    replaced: Range<usize>,
19	    replacement_len: usize,
20	) -> Range<usize> {
21	    try_reparse(text, replaced, replacement_len, None, root, 0).unwrap_or_else(|| {
22	        let id = root.span().id();
23	        *root = parse(text);
24	        if let Some(id) = id {
25	            root.numberize(id, Span::FULL).unwrap();
26	        }
27	        0..text.len()
28	    })
29	}
30	
31	/// Try to reparse inside the given node, returning the range that was
32	/// ultimately reparsed.
33	///
34	/// We start by doing a depth-first search for the innermost node or nodes which
35	/// fully surround the replaced range. This can be a single node that is a
36	/// code/content block or one or more nodes that are markup expressions and are
37	/// directly inside a markup block or the top-level markup. In either case, we
38	/// call the parser and succeed only if the parsed text has balanced delimiters
39	/// with the same delimiter nesting level as before. Otherwise, we expand the
40	/// set of markup expressions outwards or return upwards until we either get a
41	/// parse that does succeed or we parse the entire text.
42	///
43	/// Note that we currently only reparse markup expressions at the top-level or
44	/// directly inside a markup block. E.g. we don't reparse markup expressions
45	/// inside lists or headings, etc. In the past we did reparse those, but the
46	/// implementation was very buggy due to edge cases surrounding indentation and
47	/// newlines, and was eventually removed without much performance impact. It's
48	/// still potentially desireable to handle some of those cases (individual list
49	/// items can get quite long in practice), but only if the implementation can be
50	/// easily reasoned as correct and shows a measured performance improvement.
51	///
52	/// We also do not currently reparse math in any capacity, but it would not be
53	/// too difficult to include equations as another kind of block, or reparse math
54	/// expressions similarly to markup expressions.
55	fn try_reparse(
56	    text: &str,
57	    replaced: Range<usize>,
58	    replacement_len: usize,
59	    parent_kind: Option<SyntaxKind>,
60	    node: &mut SyntaxNode,
61	    offset: usize,
62	) -> Option<Range<usize>> {
63	    let (overlap, start_offset) = overlapping_children(node, replaced.clone(), offset)?;
64	
65	    let node_kind = node.kind();
66	    let children = node.children_mut();
67	
68	    if let [child] = &mut children[overlap.clone()]
69	        && start_offset < replaced.start
70	        && replaced.end < start_offset + child.len()
71	        && child.is_inner()
72	    {
73	        // A single child fully surrounds the edit. We either reparse within the
74	        // child, or reparse the child itself (if the child is a block).
75	        let prev_len = child.len();
76	        let prev_desc = child.descendants();
77	        let new_len = prev_len + replacement_len - replaced.len();
78	        let new_range = start_offset..start_offset + new_len;
79	
80	        // Recursively descend and try to reparse at a lower level.
81	        if let Some(range) = try_reparse(
82	            text,
83	            replaced.clone(),
84	            replacement_len,
85	            Some(node_kind),
86	            child,
87	            start_offset,
88	        ) {
89	            // A lower level reparse succeeded! Update this node and return the
90	            // reparsed range.
91	            assert_eq!(child.len(), new_len);
92	            let new_desc = child.descendants();
93	            node.update_parent(prev_len, new_len, prev_desc, new_desc);
94	            return Some(range);
95	        }
96	
97	        // This is the innermost block which fully surrounds the text (and
98	        // hasn't failed at reparsing yet), reparse!
99	        if child.kind().is_block()
100	            && let Some(reparsed) = reparse_block(text, new_range.clone())
101	        {
102	            // Reparsing succeeded, but we can still fail if we're out of span
103	            // numbers to assign to nodes (this is rare).
104	            return node
105	                .replace_children(overlap, vec![reparsed])
106	                .is_ok()
107	                .then_some(new_range);
108	        }
109	    }
110	
111	    if node_kind == SyntaxKind::Markup
112	        && matches!(parent_kind, None | Some(SyntaxKind::ContentBlock))
113	    {
114	        expand_and_reparse_markup(
115	            text,
116	            replaced,
117	            replacement_len,
118	            node,
119	            overlap,
120	            offset,
121	            parent_kind.is_none(),
122	        )
123	    } else {
124	        None
125	    }
126	}
127	
128	/// Reparse a range of markup expressions, expanding the range exponentially on
129	/// each iteration.
130	fn expand_and_reparse_markup(
131	    text: &str,
132	    replaced: Range<usize>,
133	    replacement_len: usize,
134	    node: &mut SyntaxNode,
135	    overlap: Range<usize>,
136	    offset: usize,
137	    top_level: bool,
138	) -> Option<Range<usize>> {
139	    let children = node.children().as_slice();
140	
141	    // Reparse a segment. Retries until it works, taking exponentially more
142	    // children into account.
143	    let mut expansion = 1;
144	    loop {
145	        // Add slack in both directions.
146	        let mut start = overlap.start.saturating_sub(expansion.max(2));
147	        let mut end = (overlap.end + expansion).min(children.len());
148	
149	        // Expand to the left.
150	        while start > 0 && expand(&children[start]) {
151	            start -= 1;
152	        }
153	
154	        // Expand to the right.
155	        while end < children.len() && expand(&children[end]) {
156	            end += 1;
157	        }
158	
159	        // Also take hash.
160	        if start > 0 && children[start - 1].kind() == SyntaxKind::Hash {
161	            start -= 1;
162	        }
163	
164	        // Synthesize what `at_start` and `nesting` would be at the start of the
165	        // reparse.
166	        let mut prefix_len = 0;
167	        let mut nesting = 0;
168	        let mut at_start = true;
169	        for child in &children[..start] {
170	            prefix_len += child.len();
171	            next_at_start(child, &mut at_start);
172	            next_nesting(child, &mut nesting);
173	        }
174	
175	        // Determine what `at_start` will have to be at the end of the reparse.
176	        let mut prev_len = 0;
177	        let mut prev_at_start_after = at_start;
178	        let mut prev_nesting_after = nesting;
179	        for child in &children[start..end] {
180	            prev_len += child.len();
181	            next_at_start(child, &mut prev_at_start_after);
182	            next_nesting(child, &mut prev_nesting_after);
183	        }
184	
185	        // Determine the range in the new text that we want to reparse.
186	        let shifted = offset + prefix_len;
187	        let new_len = prev_len + replacement_len - replaced.len();
188	        let new_range = shifted..shifted + new_len;
189	        let at_end = end == children.len();
190	
191	        // Reparse!
192	        let reparsed = reparse_markup(
193	            text,
194	            new_range.clone(),
195	            &mut at_start,
196	            &mut nesting,
197	            top_level,
198	        );
199	
200	        if let Some(newborns) = reparsed {
201	            // If more children follow, at_start must match its previous value.
202	            // Similarly, if we children follow or we not top-level the nesting
203	            // must match its previous value.
204	            if (at_end || at_start == prev_at_start_after)
205	                && ((at_end && top_level) || nesting == prev_nesting_after)
206	            {
207	                // Reparsing succeeded, but we can still fail if we're out of
208	                // span numbers to assign to nodes (this is rare).
209	                return node
210	                    .replace_children(start..end, newborns)
211	                    .is_ok()
212	                    .then_some(new_range);
213	            }
214	        }
215	
216	        // If it didn't even work with all children, we give up.
217	        if start == 0 && at_end {
218	            break;
219	        }
220	
221	        // Exponential expansion to both sides.
222	        expansion *= 2;
223	    }
224	
225	    None
226	}
227	
228	/// The indices and start offset of the children which overlap a replaced range.
229	/// Returns `None` if the children don't fully cover the range. Will never
230	/// return an empty range if it returns `Some`.
231	///
232	/// Note that the returned `Range<usize>` is the range of children in the
233	/// parent, but the returned `usize` is a byte offset in the source text.
234	fn overlapping_children(
235	    node: &SyntaxNode,
236	    range: Range<usize>,
237	    mut offset: usize,
238	) -> Option<(Range<usize>, usize)> {
239	    if !node.is_inner() || offset > range.start || range.end > offset + node.len() {
240	        // No set of children will fully cover the range, no need to search.
241	        return None;
242	    }
243	    let mut index = 0;
244	    let mut start = 0;
245	    let mut start_offset = offset;
246	    for child in node.children() {
247	        if offset < range.start {
248	            start = index;
249	            start_offset = offset;
250	        }
251	        offset += child.len();
252	        index += 1;
253	        if range.end < offset {
254	            break;
255	        }
256	    }
257	    debug_assert!(start_offset <= range.start);
258	    debug_assert!(range.end <= offset);
259	    Some((start..index, start_offset))
260	}
261	
262	/// Whether the selection should be expanded beyond a node of this kind.
263	fn expand(node: &SyntaxNode) -> bool {
264	    let kind = node.kind();
265	    kind.is_trivia()
266	        || kind.is_error()
267	        || kind == SyntaxKind::Semicolon
268	        || node.leaf_text() == "/"
269	        || node.leaf_text() == ":"
270	}
271	
272	/// Whether `at_start` would still be true after this node given the
273	/// previous value of the property.
274	fn next_at_start(node: &SyntaxNode, at_start: &mut bool) {
275	    let kind = node.kind();
276	    if kind.is_trivia() {
277	        *at_start |= kind == SyntaxKind::Parbreak
278	            || (kind == SyntaxKind::Space && node.leaf_text().chars().any(is_newline));
279	    } else {
280	        *at_start = false;
281	    }
282	}
283	
284	/// Update `nesting` based on the node.
285	fn next_nesting(node: &SyntaxNode, nesting: &mut usize) {
286	    if node.kind() == SyntaxKind::Text {
287	        match node.leaf_text().as_str() {
288	            "[" => *nesting += 1,
289	            "]" if *nesting > 0 => *nesting -= 1,
290	            _ => {}
291	        }
292	    }
293	}
