296	mod tests {
297	    use std::ops::Range;
298	
299	    use crate::{Source, Span, parse};
300	
301	    /// How to replace text in the test string.
302	    enum Edit {
303	        /// Insert at the end.
304	        End,
305	        /// Insert at an index.
306	        At(usize),
307	        /// Replace the given range.
308	        Range(Range<usize>),
309	        /// Replace the first match in the original.
310	        Match(&'static str),
311	        /// Replace at the index after the first match of this string.
312	        After(&'static str),
313	    }
314	
315	    impl Edit {
316	        #[track_caller]
317	        fn into_range(self, text: &str) -> Range<usize> {
318	            match self {
319	                Self::End => text.len()..text.len(),
320	                Self::At(index) => {
321	                    assert!(text.len() >= index, "index is out of bounds");
322	                    index..index
323	                }
324	                Self::Range(range) => {
325	                    assert!(text.len() >= range.end, "range is out of bounds");
326	                    range
327	                }
328	                Self::Match(pat) => {
329	                    let start = text.find(pat).expect("pattern must exist in original");
330	                    start..start + pat.len()
331	                }
332	                Self::After(pat) => {
333	                    let start = text.find(pat).expect("pattern must exist in original");
334	                    let end = start + pat.len();
335	                    end..end
336	                }
337	            }
338	        }
339	    }
340	
341	    /// What kind of reparsing happened.
342	    #[derive(Debug, Clone, PartialEq, Eq)]
343	    enum Reparse<'a> {
344	        /// The whole text was reparsed.
345	        All,
346	        /// The text was parsed incrementally matching this string.
347	        Incr(&'a str),
348	    }
349	
350	    #[track_caller]
351	    fn test(text: &str, edit: Edit, with: &str, expected: Reparse) {
352	        let mut source = Source::detached(text);
353	        let orig_tree = source.root().clone();
354	        // `Source::edit()` is the public interface for reparsing.
355	        let replaced_range = source.edit(edit.into_range(text), with);
356	        let mut reparsed_tree = source.root().clone();
357	        let mut normal_parse = parse(source.text());
358	        reparsed_tree.synthesize(Span::detached());
359	        normal_parse.synthesize(Span::detached());
360	        if reparsed_tree != normal_parse {
361	            eprintln!("Original source text: {text:?}");
362	            eprintln!("Original tree:\n{orig_tree:#?}");
363	            eprintln!("New source text: {:?}", source.text());
364	            eprintln!("Reparsed tree:\n{reparsed_tree:#?}");
365	            eprintln!("Normal parse tree:\n{normal_parse:#?}");
366	            panic!("Reparsed tree did not match normal parse");
367	        }
368	        let actual = if replaced_range == (0..source.text().len()) {
369	            Reparse::All
370	        } else {
371	            Reparse::Incr(&source.text()[replaced_range])
372	        };
373	        assert_eq!(actual, expected);
374	    }
375	
376	    /// Basic tests for the reparsing algorithm and the testing framework.
377	    #[test]
378	    fn test_reparse_basic() {
379	        use Reparse::*;
380	        // Replace everything with something else:
381	        test("some content", Edit::Match("some content"), "do it", All);
382	        test("some content", Edit::Range(0..12), "", All);
383	        test("", Edit::At(0), "do it", All);
384	        test("", Edit::End, "do it", All);
385	        // Add something at the end:
386	        test("some content", Edit::After("some content"), " do it", All);
387	    }
388	
389	    /// Test incremental reparsing of markup expressions.
390	    #[test]
391	    fn test_reparse_markup() {
392	        use Reparse::*;
393	        // Tilde is useful because it always creates a distinct token, whereas
394	        // spaces may join with adjacent text as one token.
395	        test("abc~def~gh~", Edit::Range(5..6), "+", Incr("abc~d+f~"));
396	        test("~~~~~~~", Edit::Range(3..4), "A", Incr("~~~A~~"));
397	        test("abc~~", Edit::Match("b"), "", Incr("ac~"));
398	        // Newlines behave slightly differently to tildes:
399	        test("~b~c~d~e", Edit::At(0), "a", Incr("a~b"));
400	        test("a~b~c~d~", Edit::End, "e", Incr("~d~e"));
401	        test("\nb\nc\nd\ne", Edit::At(0), "a", Incr("a\nb\n"));
402	        test("a\nb\nc\nd\n", Edit::End, "e", Incr("c\nd\ne"));
403	        test("#var. hello", Edit::Match(" "), " ", All);
404	        test("#var;hello", Edit::Range(9..10), "a", All);
405	        test("https:/world", Edit::After("/"), "/", All);
406	        test("hello  world", Edit::Match("world"), "walkers", All);
407	        test("a d e", Edit::Match(" d"), " b c d", All);
408	        test("~*~*~", Edit::At(2), "*", All);
409	        test("::1\n2. a\n3", Edit::After(" "), "4", Incr("1\n2. 4a\n"));
410	        test("* #{1+2} *", Edit::Match("2"), "3", Incr("{1+3}"));
411	        test("#{(0, 1, 2)}", Edit::Match("1"), "11pt", Incr("{(0, 11pt, 2)}"));
412	        test("\n= A heading", Edit::After("A"), "n evocative", All);
413	        test("#call() abc~d", Edit::After("()"), "[]", Incr("#call()[] abc"));
414	        test("a your thing a", Edit::Range(6..7), "a", All);
415	        test("#grid(columns: (auto, 1fr, 40%))", Edit::Match("auto"), "4pt", All);
416	        test(
417	            "abc\n= a head\njoke",
418	            Edit::Match("\n"),
419	            "\nmore\n\n",
420	            Incr("abc\nmore\n\n= a head\n"),
421	        );
422	        test("#show f: a => b..", Edit::End, "c", All);
423	        test("#for", Edit::End, "//", All);
424	        test("a\n#let \nb", Edit::At(7), "i", Incr("#let i\nb"));
425	        test("#{{let x = z}; a = 1} b", Edit::At(7), "//", All);
426	        test("a ```typst hello```", Edit::Range(16..17), "", All);
427	        test("a{b}c", Edit::At(1), "#", All);
428	        test("a#{b}c", Edit::Match("#"), "", All);
429	    }
430	
431	    /// Test incremental reparsing of code and content blocks.
432	    #[test]
433	    fn test_reparse_block() {
434	        use Reparse::*;
435	        test("Hello #{ x + 1 }!", Edit::Match("x"), "abc", Incr("{ abc + 1 }"));
436	        test("A#{}!", Edit::After("{"), "\"", All);
437	        test("#{ [= x] }!", Edit::After("="), "=", Incr("== x"));
438	        test("#[[]]", Edit::At(3), "\\", Incr("[[\\]]"));
439	        test("#[[ab]]", Edit::Match("b"), "\\", Incr("[[a\\]]"));
440	        test("#{}}", Edit::After("{"), "{", All);
441	        test("A: #[BC]", Edit::After("B"), "{", Incr("B{C"));
442	        test("A: #[BC]", Edit::After("B"), "#{", Incr("B#{C"));
443	        test("A: #[BC]", Edit::After("B"), "#{}", Incr("B#{}C"));
444	        test("#{\"ab\"}A", Edit::At(5), "c", Incr("{\"abc\"}"));
445	        test("#{\"ab\"}A", Edit::Range(5..6), "c", All);
446	        test("a#[]b", Edit::After("["), "#{", Incr("[#{]"));
447	        test("a#{call(); abc}b", Edit::At(8), "[]", Incr("{call([]); abc}"));
448	        test(
449	            "a #while x {\n g(x) \n}  b",
450	            Edit::After("{"),
451	            "//",
452	            Incr("{//\n g(x) \n}"),
453	        );
454	        test("a#[]b", Edit::After("["), "[hey]", Incr("[[hey]]"));
455	    }
456	
457	    /// Test unclosed strings/blocks in embedded code.
458	    #[test]
459	    fn test_reparse_unclosed_embedded() {
460	        use Reparse::*;
461	        test("#\"a\nb\nc", Edit::End, "\"", All);
462	        test("#return \"a\nb\nc", Edit::End, "\"", All);
463	        test("#import \"@preview/pkg", Edit::End, "\"", All);
464	        test("#import [a\nb\nc", Edit::End, "]", All);
465	        test("#import $a\nb\nc", Edit::End, "$", All);
466	        test("#set thing\"a\n", Edit::End, "\"", All);
467	        test("#let x = \"a\nb\nc", Edit::End, "\"", All);
468	        test("#let x = {\"a\nb\nc}", Edit::After("c"), "\"", Incr("{\"a\nb\nc\"}"));
469	        test("#if x {\"a\nb\nc", Edit::End, "\"", All);
470	        test("#if x \"a\nb\nc", Edit::End, "\"", All);
471	        test("#if x \"a\nb\nc", Edit::After("x "), "{}", All);
472	        test("#if x $a\nb\nc", Edit::End, "$", All);
473	        test("#for x in \"a\nb\nc", Edit::End, "\"", All);
474	        test("#for x \"a\nb\nc", Edit::After("x "), "in ", All);
475	    }
476	}
